window.renderNationalDayCase=(t,href)=>{
 const annual=window.renderAnnualCase(t,href);
 let reader=annual.slice(annual.indexOf('<section class="annual-stage">'),annual.indexOf('<section class="next-project">'));
 reader=reader.replaceAll('assets/annual-2025/','assets/national-day/').replaceAll('2025 业绩成绩单','国庆主题传播').replaceAll('2025 results infographic','National Day editorial').replaceAll('2025 Results','National Day editorial');
 reader=reader.replace('class="annual-stage"','class="annual-stage national-reader"');
 reader=reader.replaceAll('年报长图','国庆长图').replaceAll('annual results artwork','National Day artwork');
 reader=reader.slice(0,reader.indexOf('<dialog'));
 reader=reader.replace(/<div class="annual-note">[\s\S]*?<div class="annual-device">/,`<div class="annual-note"><p>${t('点击播放原作，再在手机内上下滑动阅读。可暂停或从头重播。','Play the original artwork, then scroll inside the phone. Pause or restart at any time.')}</p><p class="annual-language-note">${t('原始 SVG 动画 · 本地素材 · 当前不含配乐','Original SVG animation · Local assets · No soundtrack in this version')}</p><div class="annual-actions"><button type="button" data-national-toggle>${t('播放原作','Play original')}</button><button type="button" data-national-restart>${t('从头重播','Restart')}</button><a class="national-open" href="assets/national-day/original/original.html" target="_blank" rel="noopener">${t('展开原作','Open artwork')} ↗</a></div><div class="annual-progress" role="progressbar" aria-label="${t('动画播放进度','Animation progress')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span></span></div><small class="annual-percent">0:00 / 2:03</small></div><div class="annual-device">`);
 reader=reader.replace(/<div class="annual-screen"[\s\S]*?<\/div><div class="annual-homebar"/,`<iframe class="national-original-frame" src="assets/national-day/original/original.html" title="${t('国庆 SVG 原作，可播放及滚动阅读','National Day SVG artwork, with playback and scrolling')}" sandbox="allow-scripts allow-same-origin"></iframe><div class="annual-homebar"`);
 reader=reader.replace('<div class="annual-note">',`<div class="annual-note"><div class="national-qr-area"><a href="https://mp.weixin.qq.com/s/rV_QU_7tdInnjIUc6hd2zg" target="_blank" rel="noopener noreferrer" aria-label="国庆主题传播公众号原文"><img src="assets/national-day/wechat-qr.png" alt="扫描二维码查看国庆主题传播公众号原文" width="200" height="200" style="display:block;width:160px;height:160px;opacity:1!important;transform:none!important;margin:auto"></a><p class="national-qr-label">${t('扫一扫，在公众号浏览','Scan to view on WeChat')}</p></div>`);
 const qrStart=reader.indexOf('<div class="national-qr-area">');
 const qrEnd=reader.indexOf('</div><p>',qrStart)+6;
 const qr=reader.slice(qrStart,qrEnd);
 reader=reader.slice(0,qrStart)+reader.slice(qrEnd);
 const clips=[['hero','节日主视觉','Celebration key visual'],['port','港口与航线','Ports and shipping'],['smart','智慧港口','Smart ports'],['sunset','一线人物与共同祝愿','People and shared wishes']];
 const detail=`<section class="national-detail-section"><header><h2>${t('一条飘带，串联整篇。','One ribbon connects the story.')}</h2><p>${t('以蓝色海天统一场景，用红色飘带引导纵向阅读，从节日祝愿延展至港口、技术与人的故事。','Blue sea and sky unify the scenes; a red ribbon guides the vertical journey from celebration to ports, technology and people.')}</p></header><div class="national-palette"><span><i style="background:#1265a4"></i>${t('海天蓝 · 场景统一','Sea blue · Unity')}</span><span><i style="background:#df2926"></i>${t('飘带红 · 视觉引导','Ribbon red · Direction')}</span><span><i style="background:#e4b45d"></i>${t('庆典金 · 主题强调','Gold · Emphasis')}</span></div><div class="national-detail-grid national-hero-grid"><figure><video muted loop playsinline controls preload="metadata" poster="assets/national-day/hero-poster.jpg" aria-label="${t('节日主视觉','Celebration key visual')}"><source src="assets/national-day/hero.mp4" type="video/mp4"></video><figcaption>${t('节日主视觉','Celebration key visual')}</figcaption></figure></div>
 <header class="national-subheading"><h2>${t('以港口为背景，让人物说出祝愿。','People and wishes, rooted in their ports.')}</h2><p>${t('人物工作对应的港口场景 + 一线人物 + 祝福语，构成长图的主要呈现形式。','Each portrait combines the person’s port environment, frontline identity and personal wishes.')}</p></header>
 <div class="national-people-grid"><figure><img src="assets/national-day/person-wuhan.jpg" width="800" height="1220" alt="${t('武汉码头人物与祝福语','Wuhan terminal portrait and message')}"><figcaption>${t('武汉码头 · 设备技术员','Wuhan terminal · Equipment technician')}</figcaption></figure><figure><img src="assets/national-day/person-pct.jpg" width="800" height="1340" alt="${t('希腊PCT码头人物与祝福语','PCT terminal portrait and message')}"><figcaption>${t('希腊PCT码头 · 设备技术员','PCT terminal · Equipment technician')}</figcaption></figure></div>
 <header class="national-subheading"><h2>${t('以动态画面，呈现绿色智慧港口。','Green and smart ports, in motion.')}</h2><p>${t('选取四组背景动图，以动态形式呈现绿色智慧港口的实际运作情况；通过集装箱作业、海港航线与智慧调度等场景，让港口特点更生动、直观。','Four animated backgrounds illustrate the operation of green and smart ports, bringing container handling, shipping routes and smart coordination to life.')}</p></header>
 <div class="national-detail-grid national-background-grid">${clips.filter(([n])=>n!=='hero').map(([n,z,e])=>`<figure><video muted loop playsinline controls preload="metadata" poster="assets/national-day/${n}-poster.jpg" aria-label="${t(z,e)}"><source src="assets/national-day/${n}.mp4" type="video/mp4"></video><figcaption>${t(z,e)}</figcaption></figure>`).join('')}<figure><img class="national-container-motion" src="assets/national-day/original/asset-ae37bd611742e676.gif" alt="${t('集装箱堆场作业动态图','Animated container yard operations')}" loading="lazy"><figcaption>${t('集装箱堆场作业','Container yard operations')}</figcaption></figure></div></section>
 `;
 reader+=detail+`<section class="national-qr-footer">${qr}</section>`;
 return `<section class="project-header"><div class="project-title"><h1 class="page-title">${t('中远海运港口<br>国庆主题传播','COSCO SHIPPING Ports<br>National Day editorial')}</h1></div><div class="project-info"><dl><div><dt>${t('项目 / 品牌','Project / Brand')}</dt><dd>${t('中远海运港口有限公司','COSCO SHIPPING Ports Limited')}</dd></div><div><dt>${t('年份','Year')}</dt><dd>2026</dd></div><div><dt>${t('服务类别','Category')}</dt><dd>${t('新媒体传播与内容创意','Digital & Social Content')}</dd></div><div><dt>${t('服务内容','Services')}</dt><dd>${t('节日主题 / 公众号长图 / 动态视觉','Seasonal campaign / WeChat editorial / Motion visuals')}</dd></div></dl><div class="project-description"><span class="number">${t('项目介绍','About the project')}</span><p>${t('以国庆为主题，将港口场景与一线人物串联为连续的公众号长图。蓝色海天构成统一背景，红色飘带贯穿不同岗位与场景，结合金色节日元素、人物图像与动态片段，呈现品牌与劳动者的共同表达。','A National Day editorial connecting port environments and frontline people in a continuous WeChat story. Blue sea and sky set the scene; a red ribbon links different roles and locations, alongside gold accents, portraits and motion sequences.')}</p></div></div></section>${reader}<section class="next-project"><a href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=hongshan')}"><span>${t('下一个项目','Next project')}</span><strong>${t('红山 · 森灵野集','Hongshan · Woodtopia')} ↗</strong></a></section>`;
};
document.addEventListener('DOMContentLoaded',()=>{
 const frame=document.querySelector('.national-original-frame');if(!frame)return;
 const en=document.documentElement.lang==='en',button=document.querySelector('[data-national-toggle]');
 const command=action=>frame.contentWindow.postMessage({type:'national-original-command',action},location.origin);
 button.addEventListener('click',()=>command('toggle'));document.querySelector('[data-national-restart]').addEventListener('click',()=>command('restart'));
 window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==frame.contentWindow||event.data?.type!=='national-original-state')return;
 const state=event.data;button.textContent=state.playing?(en?'Pause':'暂停'):(state.started?(en?'Continue':'继续播放'):(en?'Play original':'播放原作'));
 const time=Math.min(123,Math.max(0,Number(state.time)||0)),percent=time/123*100,bar=document.querySelector('.annual-progress');bar.setAttribute('aria-valuenow',Math.round(percent));bar.firstElementChild.style.width=percent+'%';document.querySelector('.annual-percent').textContent=Math.floor(time/60)+':'+String(Math.floor(time%60)).padStart(2,'0')+' / 2:03';
 });
 document.addEventListener('visibilitychange',()=>{if(document.hidden)frame.contentWindow.postMessage({type:'national-original-command',action:'pause'},location.origin)});
});

document.addEventListener('DOMContentLoaded',()=>{const videos=[...document.querySelectorAll('.national-detail-grid video')];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting&&!reduced)target.play().catch(()=>{});else target.pause()}),{threshold:.25});videos.forEach(v=>observer.observe(v));document.addEventListener('visibilitychange',()=>{if(document.hidden)videos.forEach(v=>v.pause())})});
